import os

def safe_open_scratch(path: str, mode: str = "r"):
    """Refuse to open path if it is or resolves through a symlink."""
    if os.path.islink(path):
        raise PermissionError(f"Symlink refused in scratch area: {path}")
    # O_NOFOLLOW on POSIX: OSError if final component is a symlink
    flags = os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0)
    fd = os.open(path, flags)
    return os.fdopen(fd, mode)

import os

_LOCAL = os.path.realpath(os.path.expanduser("~/lib/table/ark/dot-local"))

def assert_not_local(data_path: str) -> None:
    """Raise hard error if data_path is inside dot-local. Article-0 enforcement."""
    if os.path.realpath(data_path).startswith(_LOCAL):
        raise RuntimeError(
            f"Article-0 violation: dot-local path in scratch write: {data_path}"
        )
